// Exact single-ciphertext KS replay. Reference files are generated by TFHE-rs.
// Optionally includes the KSK loader/cache with a behavioral AXI memory model.
module tb_pep_key_switch_vector;
  import common_definition_pkg::*;
  import param_tfhe_pkg::*;
  import pep_common_param_pkg::*;
  import pep_ks_common_param_pkg::*;
  `timescale 1ns/1ps
  parameter string VECTOR_DIR = "";
  parameter int MAX_CYCLES = 200000;
  parameter bit INJECT_REF_ERROR = 0; // Negative control; never used for a pass.
  parameter bit USE_KSK_PIPE = 0;
  parameter bit AXI_STAGGER = 0;
  parameter bit INJECT_MEM_ERROR = 0;
  localparam int SW = 4;
  localparam int CW = 8;
  localparam int PER_COL = KS_BLOCK_LINE_NB * KS_LG_NB;
  localparam int PER_LANE = KS_BLOCK_COL_NB * PER_COL;
  localparam int KEY_WORDS = PER_LANE * LBX * LBY;
  localparam int USED_KEY_WORDS = (LWE_K+1) * PER_COL * LBY;

  bit clk = 0;
  always #1 clk = ~clk;
  bit s_rst_n = 0;
  logic [MOD_Q_W-1:0] input_mem [0:BLWE_K];
  logic [63:0] key_mem [0:KEY_WORDS-1];
  logic [63:0] ref_lwe [0:LWE_K-1];
  logic [63:0] ref_corr [0:LWE_K-1];
  logic [63:0] ref_body [0:0];
  bit loaded = 0;
  bit start_commands = 0;
  logic enquiry, command_avail, key_loaded;
  ks_cmd_t command;
  logic [KS_BATCH_CMD_W-1:0] batch_cmd;
  logic batch_avail;
  logic [SW-1:0] wr_en = '0, wr_last = '0;
  logic [SW-1:0][PID_W-1:0] wr_pid = '0;
  logic [SW-1:0][CW-1:0][MOD_Q_W-1:0] wr_data = '0;
  logic [LBX-1:0][LBY-1:0][LBZ-1:0][MOD_KSK_W-1:0] ksk;
  logic [LBX-1:0][LBY-1:0] ksk_vld, ksk_rdy;
  ks_result_t result;
  logic result_vld;
  logic body_en, body_parity;
  logic [MOD_KSK_W-1:0] body;
  logic [PID_W-1:0] body_pid;
  pep_ks_error_t ks_error;
  integer credits = 0, commands = 0, results = 0, bodies = 0, cycles = 0;
  integer key_pos [LBX][LBY];
  bit [LWE_K-1:0] seen = '0;

  pep_key_switch #(
    .KS_IF_SUBW_NB(SW), .KS_IF_COEF_NB(CW),
    .ALMOST_DONE_BLINE_ID(KS_BLOCK_LINE_NB-2)
  ) dut (
    .clk(clk), .s_rst_n(s_rst_n),
    .ks_seq_cmd_enquiry(enquiry), .seq_ks_cmd(command),
    .seq_ks_cmd_avail(command_avail), .inc_ksk_wr_ptr(key_loaded),
    .batch_cmd(batch_cmd), .batch_cmd_avail(batch_avail),
    .ldb_blram_wr_en(wr_en), .ldb_blram_wr_pid(wr_pid),
    .ldb_blram_wr_data(wr_data), .ldb_blram_wr_pbs_last(wr_last),
    .ksk(ksk), .ksk_vld(ksk_vld), .ksk_rdy(ksk_rdy),
    .ks_seq_result(result), .ks_seq_result_vld(result_vld),
    .ks_seq_result_rdy(1'b1), .boram_wr_en(body_en),
    .boram_data(body), .boram_pid(body_pid), .boram_parity(body_parity),
    .reset_cache(1'b0), .ks_error(ks_error)
  );

  // One ciphertext at pid 0, one command per block column. Keep every field
  // initialized, including parity. In direct mode the key is preloaded; cached
  // mode waits for the real loader's key-slot notification.
  always_comb begin
    command = '0;
    command.ks_loop = commands * LBX;
    command.wp.pt = 1;
    command_avail = s_rst_n && start_commands && credits > 0 && commands < KS_BLOCK_COL_NB;
  end
  always @(posedge clk) begin
    if (!s_rst_n) begin
      credits <= 0;
      commands <= 0;
    end else begin
      credits <= credits + int'(enquiry) - int'(command_avail);
      commands <= commands + int'(command_avail);
      if (credits < 0) $fatal(1, "Command credit underflow");
    end
  end

  if (USE_KSK_PIPE) begin : cache_path
    logic batch_start;
    always @(posedge clk)
      if (!s_rst_n) batch_start <= 0;
      else batch_start <= command_avail && commands == 0;
    ks_vector_cached_source #(
      .VECTOR_DIR(VECTOR_DIR), .AXI_STAGGER(AXI_STAGGER),
      .INJECT_MEM_ERROR(INJECT_MEM_ERROR)
    ) source (
      .clk(clk), .s_rst_n(s_rst_n), .loaded(loaded),
      .batch_start(batch_start), .batch_cmd(batch_cmd), .batch_avail(batch_avail),
      .key_loaded(key_loaded), .ksk(ksk), .ksk_vld(ksk_vld), .ksk_rdy(ksk_rdy)
    );
  end else begin : direct_path
    always @(posedge clk)
      if (!s_rst_n) key_loaded <= 0;
      else key_loaded <= command_avail;
  end

  for (genvar x=0; x<LBX; x++) begin : gx
    for (genvar y=0; y<LBY; y++) begin : gy
      integer word_index;
      always_comb begin
        word_index = (((key_pos[x][y] / PER_COL) * LBX + x) * PER_COL
                     + key_pos[x][y] % PER_COL) * LBY + y;
      end
      if (!USE_KSK_PIPE) begin : direct_source
        always_comb begin
          ksk_vld[x][y] = loaded && s_rst_n && key_pos[x][y] < PER_LANE;
          ksk[x][y] = '0;
          if (ksk_vld[x][y]) ksk[x][y] = key_mem[word_index][LBZ*MOD_KSK_W-1:0];
        end
      end
      always @(posedge clk)
        if (!s_rst_n) key_pos[x][y] <= 0;
        else if (ksk_vld[x][y] && ksk_rdy[x][y]) begin
          if (key_pos[x][y] >= PER_LANE) $fatal(1, "Extra KSK word x=%0d y=%0d", x,y);
          // The loader intentionally omits columns >= LWE_K+1. The manager
          // still drains these lanes, and pep_ks_out_process discards them;
          // their stale RAM contents are not part of the key contract.
          if (!USE_KSK_PIPE || (key_pos[x][y] / PER_COL)*LBX+x < LWE_K+1)
            if ($isunknown(ksk[x][y]) ||
                ksk[x][y] !== key_mem[word_index][LBZ*MOD_KSK_W-1:0])
              $fatal(1, "KSK stream mismatch x=%0d y=%0d word=%0d expected=%h actual=%h",
                     x,y,key_pos[x][y],key_mem[word_index],ksk[x][y]);
          key_pos[x][y] <= key_pos[x][y] + 1;
        end
    end
  end

  initial begin
    if (VECTOR_DIR == "") $fatal(1, "VECTOR_DIR is required");
    if (N != 2048 || GLWE_K != 1 || LWE_K != 879 || MOD_Q_W != 64 ||
        PBS_B_W != 23 || PBS_L != 1 || MOD_KSK_W != 21 || KS_L != 8 ||
        KS_B_W != 2 || LBX != 3 || LBY != 64 || LBZ != 3 || !USE_MEAN_COMP ||
        BATCH_PBS_NB != 12 || TOTAL_PBS_NB != 27)
      $fatal(1, "Unexpected fixture parameters");
    $readmemh({VECTOR_DIR,"/input.hex"}, input_mem);
    $readmemh({VECTOR_DIR,"/ksk.hex"}, key_mem);
    $readmemh({VECTOR_DIR,"/expected_lwe.hex"}, ref_lwe);
    $readmemh({VECTOR_DIR,"/expected_corr.hex"}, ref_corr);
    $readmemh({VECTOR_DIR,"/expected_body.hex"}, ref_body);
    foreach (input_mem[i])
      if ($isunknown(input_mem[i])) $fatal(1, "Missing/unknown input coefficient %0d", i);
    foreach (ref_lwe[i])
      if ($isunknown(ref_lwe[i]) || $isunknown(ref_corr[i]))
        $fatal(1, "Missing/unknown reference coefficient %0d", i);
    if ($isunknown(ref_body[0])) $fatal(1, "Missing/unknown reference body");
    if (INJECT_REF_ERROR) ref_lwe[0] = ref_lwe[0] ^ 64'd1;
    loaded = 1;
    repeat (10) @(negedge clk);
    s_rst_n = 1;
    // Four 8-coefficient write lanes. Mark the last mask transfer on lanes
    // 1..3; lane 0 terminates on the subsequent body transfer.
    for (int offset=0; offset<BLWE_K; offset+=SW*CW) begin
      @(negedge clk);
      wr_en = '1;
      wr_last = offset + SW*CW == BLWE_K ? 4'b1110 : '0;
      for (int s=0; s<SW; s++)
        for (int c=0; c<CW; c++) wr_data[s][c] = input_mem[offset+s*CW+c];
    end
    @(negedge clk);
    wr_en = 1;
    wr_last = 1;
    wr_data = '0;
    wr_data[0][0] = input_mem[BLWE_K];
    @(negedge clk);
    wr_en = '0;
    wr_last = '0;
    repeat (64) @(negedge clk);
    start_commands = 1;
    wait (results == LWE_K && bodies == 1);
    // Drain the fixed pipeline; check duplicate/late outputs before success.
    repeat (128) @(negedge clk);
    if (commands != KS_BLOCK_COL_NB || seen !== {LWE_K{1'b1}})
      $fatal(1, "Incomplete scoreboard");
    for (int x=0; x<LBX; x++)
      for (int y=0; y<LBY; y++)
        if (key_pos[x][y] != PER_LANE)
          $fatal(1, "Incomplete key consumption x=%0d y=%0d words=%0d", x,y,key_pos[x][y]);
    $display("KS_VECTOR_PASS: %0d coefficients, corrections and body match CPU; cycles=%0d", results, cycles);
    if (USE_KSK_PIPE)
      $display("KSK_PIPE_PASS: %0d used packed key words matched; %0d unused words drained; stagger=%0d",
               USED_KEY_WORDS, KEY_WORDS-USED_KEY_WORDS, AXI_STAGGER);
    $finish;
  end

  always @(posedge clk) if (s_rst_n) begin
    cycles <= cycles + 1;
    if (cycles == MAX_CYCLES)
      $fatal(1, "KS watchdog: commands=%0d results=%0d bodies=%0d", commands, results, bodies);
    if (ks_error !== '0) $fatal(1, "KS error or unknown: %h", ks_error);
    if (result_vld) begin
      if (result.ks_loop >= LWE_K || result.ks_loop !== results)
        $fatal(1, "Unexpected KS output index: expected=%0d got=%0d", results, result.ks_loop);
      if (result.rp !== '0 || result.wp !== (PID_W+1)'(1))
        $fatal(1, "Unexpected output pointers");
      if (seen[result.ks_loop]) $fatal(1, "Duplicate output");
      if (result.lwe_a[0] !== ref_lwe[result.ks_loop][LWE_COEF_W-1:0])
        $fatal(1, "KS coefficient mismatch index=%0d expected=%h actual=%h", result.ks_loop,
               ref_lwe[result.ks_loop], result.lwe_a[0]);
      if (result.corr_a[0] !== ref_corr[result.ks_loop][KS_CORR_W-1:0])
        $fatal(1, "KS correction mismatch index=%0d expected=%h actual=%h", result.ks_loop,
               ref_corr[result.ks_loop], result.corr_a[0]);
      seen[result.ks_loop] <= 1;
      results <= results + 1;
      if (results % 100 == 0) $display("KS_VECTOR checked coefficient %0d", results);
    end
    if (body_en) begin
      if (bodies != 0 || body_pid !== '0 || body_parity !== 1'b0 ||
          body !== ref_body[0][MOD_KSK_W-1:0])
        $fatal(1, "KS body mismatch expected=%h actual=%h pid=%0d parity=%b", ref_body[0],body,body_pid,body_parity);
      bodies <= bodies + 1;
    end
  end
endmodule
